Your expense tracker is below. Add an expense, set a monthly budget, and it shows your total, what's left and a split by category. Entries last while this page stays open.

```page
<!DOCTYPE html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<style>
body{font-family:Segoe UI,system-ui,sans-serif;margin:0;padding:16px;background:#f6f7f5;color:#1d2b24}
h2{margin:0 0 12px;font-size:20px}
.card{background:#fff;border-radius:12px;padding:14px;margin-bottom:12px;box-shadow:0 1px 3px #0001}
.row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px}
input,select{padding:8px;border:1px solid #cfd6d1;border-radius:8px;font-size:14px;flex:1;min-width:110px}
button{padding:8px 14px;border:0;border-radius:8px;background:#2f7d5b;color:#fff;font-size:14px;cursor:pointer}
button.x{background:#c0504d;padding:4px 9px}
.stats{display:flex;gap:10px;flex-wrap:wrap}
.stat{flex:1;min-width:110px}
.stat b{display:block;font-size:20px}
.stat span{font-size:12px;color:#5b6b62}
.bar{height:8px;background:#e3e8e4;border-radius:4px;overflow:hidden;margin:3px 0 8px}
.bar i{display:block;height:100%;background:#2f7d5b}
.over{color:#c0504d}
table{width:100%;border-collapse:collapse;font-size:14px}
td{padding:6px 4px;border-bottom:1px solid #eee}
td.a{text-align:right}
.empty{color:#7a877f;font-size:14px}
</style></head><body>
<h2>Monthly expenses</h2>

<div class="card">
  <div class="row">
    <input id="desc" placeholder="What was it?">
    <input id="amt" type="number" min="0" placeholder="Amount (₹)">
  </div>
  <div class="row">
    <select id="cat">
      <option>Food</option><option>Rent</option><option>Travel</option><option>Bills</option>
      <option>Shopping</option><option>Health</option><option>Fun</option><option>Other</option>
    </select>
    <input id="dt" type="date">
    <button onclick="add()">Add</button>
  </div>
</div>

<div class="card">
  <div class="row"><input id="bud" type="number" min="0" placeholder="Monthly budget (₹)" oninput="render()"></div>
  <div class="stats">
    <div class="stat"><b id="tot">₹0</b><span>Spent</span></div>
    <div class="stat"><b id="left">–</b><span>Left</span></div>
    <div class="stat"><b id="cnt">0</b><span>Entries</span></div>
  </div>
</div>

<div class="card"><div id="cats"><span class="empty">Category split appears here.</span></div></div>

<div class="card"><table id="list"></table></div>

<script>
var items=[];
var $=function(i){return document.getElementById(i)};
function inr(n){return "₹"+Math.round(n).toLocaleString("en-IN")}
function esc(s){return s.replace(/[&<>"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]})}
$("dt").value=new Date().toISOString().slice(0,10);
function add(){
  var a=parseFloat($("amt").value);
  if(!(a>0)){$("amt").focus();return}
  items.push({d:$("desc").value.trim()||$("cat").value,a:a,c:$("cat").value,t:$("dt").value});
  $("desc").value="";$("amt").value="";
  render();
}
function del(i){items.splice(i,1);render()}
function render(){
  var tot=items.reduce(function(s,x){return s+x.a},0);
  $("tot").textContent=inr(tot);
  $("cnt").textContent=items.length;
  var b=parseFloat($("bud").value);
  var l=$("left");
  if(b>0){l.textContent=inr(b-tot);l.className=(b-tot<0)?"over":""}else{l.textContent="–";l.className=""}
  var by={};items.forEach(function(x){by[x.c]=(by[x.c]||0)+x.a});
  var keys=Object.keys(by).sort(function(p,q){return by[q]-by[p]});
  $("cats").innerHTML=keys.length?keys.map(function(k){
    var p=tot?by[k]/tot*100:0;
    return "<div><span>"+k+" · "+inr(by[k])+" ("+Math.round(p)+"%)</span><div class='bar'><i style='width:"+p+"%'></i></div></div>";
  }).join(""):"<span class='empty'>Category split appears here.</span>";
  $("list").innerHTML=items.length?items.map(function(x,i){return ""}).length&&items.map(function(x,i){
    return "<tr><td>"+esc(x.d)+"<br><small>"+x.c+" · "+x.t+"</small></td><td class='a'>"+inr(x.a)+"</td><td><button class='x' onclick='del("+i+")'>×</button></td></tr>";
  }).reverse().join(""):"<tr><td class='empty'>No expenses yet. Add your first one above.</td></tr>";
}
render();
</script>
</body></html>
```
